#define MAX_D 26
#define MAX_TYPES 26

int D;
int c[MAX_TYPES];
int s[MAX_D][MAX_TYPES];
int last[MAX_TYPES];

int compute_penalty(int type, int day) {
    return c[type] * (day - last[type]);
}

int main() {
    scanf("%d", &D);
    for (int i = 0; i < MAX_TYPES; i++) {
        scanf("%d", &c[i]);
    }
    for (int d = 0; d < D; d++) {
        for (int i = 0; i < MAX_TYPES; i++) {
            scanf("%d", &s[d][i]);
        }
    }

    // Initialize last held day for each type to 0 (before day 1)
    for (int i = 0; i < MAX_TYPES; i++) {
        last[i] = 0;
    }

    int total = 0;
    for (int d = 0; d < D; d++) {
        int best_type = 0;
        int best_gain = -1000000000;

        for (int t = 0; t < MAX_TYPES; t++) {
            // Gain from holding type t today
            int gain = s[d][t];
            // Penalty for not holding other types
            int penalty = 0;
            for (int i = 0; i < MAX_TYPES; i++) {
                if (i == t) continue;
                penalty += compute_penalty(i, d + 1);
            }
            // Penalty for this type itself (it will be held today, so no penalty)
            // But we need to consider that last[t] will be updated after today
            // So the penalty for t is 0 for today
            int net = gain - penalty;
            if (net > best_gain) {
                best_gain = net;
                best_type = t;
            }
        }

        // Update satisfaction
        total += s[d][best_type];
        for (int i = 0; i < MAX_TYPES; i++) {
            if (i != best_type) {
                total -= c[i] * (d + 1 - last[i]);
            }
        }
        last[best_type] = d + 1;

        printf("%d\n", best_type + 1);
    }

    return 0;
}

