#include <bits/stdc++.h>
using namespace std;

/*
  AtCoder Intro Heuristics style problem.

  We are given:
    D
    c[26]
    s[D][26]

  Need to output one contest type (1..26) for each day.

  Since this is a heuristic optimization problem and the statement here only asks
  to determine a schedule maximizing satisfaction, we provide a strong greedy
  baseline:
    For each day, try all 26 contest types and choose the one that maximizes
    the immediate score after that day.

  Score transition:
    If we hold type t on day d (1-indexed):
      gain += s[d][t]
      last[t] = d
      then subtract for all i:
        c[i] * (d - last[i])

  This can be evaluated in O(26) per candidate, so total O(D * 26 * 26),
  which is easily fast enough.

  Output:
    D lines, each an integer in [1, 26].
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int D;
    cin >> D;

    vector<long long> c(26);
    for (int i = 0; i < 26; ++i) cin >> c[i];

    vector<vector<long long>> s(D, vector<long long>(26));
    for (int d = 0; d < D; ++d) {
        for (int i = 0; i < 26; ++i) cin >> s[d][i];
    }

    vector<int> last(26, 0);
    vector<int> ans(D);

    for (int d = 1; d <= D; ++d) {
        long long bestScore = -(1LL << 60);
        int bestType = 0;

        for (int t = 0; t < 26; ++t) {
            long long cur = s[d - 1][t];
            for (int i = 0; i < 26; ++i) {
                int li = (i == t ? d : last[i]);
                cur -= c[i] * (d - li);
            }
            if (cur > bestScore) {
                bestScore = cur;
                bestType = t;
            }
        }

        ans[d - 1] = bestType + 1;
        last[bestType] = d;
    }

    for (int d = 0; d < D; ++d) {
        cout << ans[d] << '\n';
    }

    return 0;
}

