                }
                // For candidate i, after updating last[i] to d+1, the penalty term for i becomes 0
                long penaltyForI = c[i] * (d + 1 - last[i]);
                long newPenalty = totalPenalty - penaltyForI;
                long totalGain = s[d][i] - newPenalty;
                // But we should compare relative to not choosing anything? Actually we must choose one.
