                // Let's just compute the total satisfaction if we pick i
                // We'll maintain satisfaction incrementally
                // For greedy, we can compute the immediate contribution
                long contribution = s[d][i];
                for (int j = 0; j < 26; j++) {
                    contribution -= c[j] * (d + 1 - last[j]);
                }
                contribution += c[i] * (d + 1 - last[i]); // because for the chosen type, penalty is removed
                // Actually: V after = V before + s[d][i] - sum_j c[j] * (d+1 - last[j]) + c[i]*(d+1 - last[i])
                // = V before + s[d][i] - sum_{j != i} c[j]*(d+1 - last[j])
                // So the change = s[d][i] - sum_{j != i} c[j]*(d+1 - last[j])
                long change = s[d][i];
                for (int j = 0; j < 26; j++) {
