        for (int d = 0; d < D; d++) {
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < 26; i++) {
                s[d][i] = Integer.parseInt(st.nextToken());
            }
        }

        long totalC = 0;
        for (int i = 0; i < 26; i++) totalC += c[i];

        long[] dp = new long[26];
        for (int i = 0; i < 26; i++) {
            dp[i] = s[0][i] - totalC + c[i];
        }

        for (int d = 1; d < D; d++) {
            long maxPrev = Long.MIN_VALUE;
            for (int i = 0; i < 26; i++) maxPrev = Math.max(maxPrev, dp[i]);
            long[] ndp = new long[26];
            for (int j = 0; j < 26; j++) {
                ndp[j] = maxPrev + s[d][j] - totalC + c[j];
            }
            dp = ndp;
        }

        long ans = Long.MIN_VALUE;
        for (int i = 0; i < 26; i++) ans = Math.max(ans, dp[i]);
        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int D;
    static int[] c = new int[26];
    static int[][] s;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        D = fs.nextInt();
        for (int i = 0; i < 26; i++) c[i] = fs.nextInt();

        s = new int[D][26];
        for (int d = 0; d < D; d++) {
            for (int i = 0; i < 26; i++) {
                s[d][i] = fs.nextInt();
            }
        }

        // Greedy construction:
        // For each day, choose the contest maximizing
        // immediate gain + a small lookahead effect.
        int[] last = new int[26];
        Arrays.fill(last, 0);

        StringBuilder out = new StringBuilder();

        for (int day = 1; day <= D; day++) {
            int bestType = 0;
            long bestScore = Long.MIN_VALUE;

            for (int type = 0; type < 26; type++) {
                long score = evaluate(day, type, last);
                if (score > bestScore) {
                    bestScore = score;
                    bestType = type;
                }
            }

            last[bestType] = day;
            out.append(bestType + 1).append('\n');
        }

        System.out.print(out.toString());
    }

    // Heuristic evaluation for choosing contest "type" on "day"
    static long evaluate(int day, int type, int[] last) {
        long score = s[day - 1][type];

        // Penalty of the current day after holding this type
        for (int i = 0; i < 26; i++) {
            int prev = last[i];
            if (i == type) prev = day;
            score -= (long) c[i] * (day - prev);
        }

        // Small lookahead:
        // reward choosing a type that would otherwise incur future penalties
        int horizon = 15;
        int end = Math.min(D, day + horizon);
        for (int future = day + 1; future <= end; future++) {
            score += (long) c[type] * (future - day);
        }

        return score;
    }
}
